 for(const mode of ['year','all']){$('#mode-'+mode).classList.toggle('selected',state.mode===mode);$('#mode-'+mode).setAttribute('aria-pressed',String(state.mode===mode));}
 $('#kind-tabs').innerHTML=['all','polity','event','place','person'].map(k=>`<button data-action="kind" data-id="${k}" class="${kind===k?'selected':''}" aria-pressed="${kind===k}">${k==='all'?t('all'):localized(KINDS[k])}</button>`).join('');
 $('#results-heading').textContent=`${visible.length} ${t('records')}${state.savedOnly?' · '+t('saved'):''}`;
