function countryMatches(query){
 const q=String(query||'').trim().normalize('NFKC').toLocaleLowerCase();
 return contemporary.features.filter(f=>!q||[f.properties.name.en,f.properties.name.zh,f.properties.code,...(f.properties.aliases||[])].some(v=>String(v).normalize('NFKC').toLocaleLowerCase().includes(q)))
  .sort((a,b)=>localized(a.properties.name).localeCompare(localized(b.properties.name),state.lang==='zh'?'zh':'en'));
}
function countryButton(f){const p=f.properties;return `<button class="country-card" data-action="country" data-id="${esc(p.id)}"><strong>${esc(localized(p.name))}</strong><small>${t(p.category)} · ${esc(p.code)}</small><span>↗</span></button>`;}
function renderStoryList(){

 const unfiltered=state.mode==='year'&&state.region==='all'&&state.theme==='all'&&kind==='all'&&!state.query&&!state.savedOnly;
 const current=currentCoverage().mode==='contemporary';
 const key=JSON.stringify([state.year,state.mode,state.region,state.theme,state.query,state.savedOnly,kind,state.lang]);if(key!==listKey){listKey=key;listLimit=80;}
 const primary=visible.length?visible.slice(0,listLimit).map(storyCard).join('')+(visible.length>listLimit?`<button class="list-more" data-action="more-entries">${t('moreEntries')} · ${listLimit} / ${visible.length}</button>`:''):`<div class="empty-state"><strong>${t('emptyTitle')}</strong>${t('empty')}<br><button data-action="browse-all">${t('browseAll')}</button></div>`;
 let suggestions='';
 if(unfiltered&&state.year>=1900&&visible.length<6){
  const recent=records.filter(r=>inferKind(r)==='event'&&r.start<state.year&&r.start>=state.year-60).sort((a,b)=>b.start-a.start).slice(0,8);
  if(recent.length)suggestions=`<section class="recent-history"><h3>${t('recentHistory')}</h3><p>${t('recentHistoryNote')}</p>${recent.map(storyCard).join('')}</section>`;
 }
 const around=state.mode==='year'&&!state.savedOnly&&['all','event'].includes(kind)&&['all','states'].includes(state.theme)?nearbyTurningPoints(records,state.year,{region:state.region,query:state.query,limit:state.region==='all'?6:10,maxDistance:state.year<500?120:state.year<1900?50:15}).filter(r=>!visible.some(v=>v.id===r.id)):[];
 const nearHTML=around.length?`<section class="nearby-reading"><h3>${state.lang==='zh'?'这一年前后的事件':'Events around this year'}</h3><p>${state.lang==='zh'?'各条目保留自己的日期；并非都发生于所选年份。':'Each entry keeps its own date; these are not all events of the selected year.'}</p>${around.map(storyCard).join('')}</section>`:'';
 let html=current&&unfiltered?`<button class="reference-entry" data-action="countries"><strong>◎ ${t('countries')}</strong><span>${contemporary.features.length} · ${t('contemporary')} ${contemporaryData.reviewedYear} ↗</span></button>${suggestions}<section class="recent-history"><h3>${state.lang==='zh'?'延续至今的条目':'Entries continuing into this year'} · ${visible.length}</h3>${primary}</section>`:primary+suggestions;
 html+=current&&unfiltered?'':nearHTML;
 if(current&&unfiltered)$('#results-heading').textContent=state.lang==='zh'?'探索近现代世界':'Explore the modern world';
 if(state.query&&state.region==='all'&&state.theme==='all'&&!state.savedOnly&&['all','place'].includes(kind)){const matches=countryMatches(state.query);if(matches.length)html+=`<section class="country-search-matches"><h3>${t('referenceMatches')} · ${contemporaryData.reviewedYear}</h3>${matches.slice(0,6).map(countryButton).join('')}<button class="text-button" data-action="countries">${t('countries')} ↗</button></section>`;}
 if((state.query||['person','place'].includes(kind))&&discovery&&!state.savedOnly&&state.theme==='all'){
  const options={region:state.region,year:state.mode==='year'?state.year:undefined,kind:kind==='all'?undefined:kind},visibleIds=new Set(visible.map(r=>r.id));
  const matches=['all','person','place'].includes(kind)?discovery.search(state.query,options).filter(r=>!r.recordId||!visibleIds.has(r.recordId)):[];
  const references=state.query&&kind==='all'?historyReferences.search(state.query,{region:state.region,year:options.year,limit:6}):[];
  const items=[...matches.slice(0,8),...references];
  if(items.length){const more=matches.length>8?`<div class="button-row">${matches.some(r=>r.kind==='person')?`<button class="text-button" data-action="browse-people">${t('people')} · ${state.lang==='zh'?'查看全部匹配':'Browse matches'} ↗</button>`:''}${matches.some(r=>r.kind==='place')?`<button class="text-button" data-action="browse-places">${t('places')} · ${state.lang==='zh'?'查看全部匹配':'Browse matches'} ↗</button>`:''}</div>`:'';
   const additional=`<section class="discovery-search-results"><h3>${state.lang==='zh'?'人物、地名与关联':'Names, places & connections'}</h3>${items.map(r=>`<button data-action="${esc(r.action)}" data-id="${esc(r.id)}"><strong>${esc(localized(r.name||r.title))}</strong><small>${esc(r.kind==='person'?t('people'):r.kind==='place'?t('places'):r.kind==='calendar'?t('calendars'):r.kind==='period'?t('periodGuides'):t('journeys'))} ↗</small></button>`).join('')}${more}</section>`;
   html=additional+(visible.length?html:'');
  }
 }
 if(earlyChinaGuide&&/^(虞|有虞氏?|舜|虞舜|夏|商|周|yu|shun|xia|shang|zhou)$/i.test(state.query.trim()))html=earlyChinaButton()+html;
 $('#stories').innerHTML=html;
}
